import {T,mesh,box} from './visuals3.js';
export function fishingRod(){let r=new T.Group();let shaft=mesh(new T.CylinderGeometry(.035,.05,1.75,10),'#aa8861',0,0,.83,r);shaft.rotation.x=Math.PI/2;let handle=mesh(new T.CylinderGeometry(.055,.055,.34,12),'#655246',0,0,.02,r);handle.rotation.x=Math.PI/2;for(let z of [.3,.8,1.3,1.68]){let eye=mesh(new T.TorusGeometry(.045,.012,5,12),'#d2d9d0',0,.035,z,r);eye.rotation.y=Math.PI/2}let reel=mesh(new T.CylinderGeometry(.085,.085,.12,14),'#9aa6a2',.075,-.08,.2,r);reel.rotation.z=Math.PI/2;box(.17,-.08,.2,.1,.035,.035,'#d6b77c',r);return r}
export class CastGesture{
constructor(onLaunch,onCancel){this.onLaunch=onLaunch;this.onCancel=onCancel;this.active=false;this.panel=document.createElement('section');this.panel.id='castPanel';this.panel.hidden=true;this.panel.innerHTML='<div class="castHead"><small>LANÇAR A LINHA</small><button id="cancelCast">Voltar</button></div><h3>Um movimento suave.</h3><p>Comece no círculo de baixo e deslize até a estrela. Solte para lançar.</p><div id="castSwipe"><span class="castEnd">Destino</span><svg viewBox="0 0 40 100" aria-hidden="true"><path d="M20 88V14m-8 10 8-10 8 10" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="4 5"/></svg><i id="castThumb"></i></div><small id="castFeedback">Deslize para cima seguindo a guia.</small><button id="assistCast">Usar lançamento assistido</button>';document.body.append(this.panel);let pad=this.panel.querySelector('#castSwipe');this.pad=pad;pad.onpointerdown=e=>{e.preventDefault();let r=pad.getBoundingClientRect();if(e.clientY<r.top+r.height*.58){this.feedback('Comece pelo círculo de baixo.');return}this.id=e.pointerId;this.origin={x:e.clientX,y:e.clientY};this.progress=0;this.invalid=false;pad.setPointerCapture(e.pointerId)};pad.onpointermove=e=>{if(e.pointerId!==this.id)return;e.preventDefault();let r=pad.getBoundingClientRect();this.follow(e.clientX-this.origin.x,this.origin.y-e.clientY,r.height)};pad.onpointerup=e=>{if(e.pointerId!==this.id)return;this.id=null;if(this.progress>=.66&&!this.invalid)this.launch();else{this.feedback('Continue até o alto da guia e solte.');this.cancelGesture()}};for(let ev of ['pointercancel','lostpointercapture'])pad.addEventListener(ev,()=>this.cancelGesture());this.panel.querySelector('#cancelCast').onclick=()=>{this.close();onCancel()};this.panel.querySelector('#assistCast').onclick=()=>{this.progress=.8;this.launch()}}
open(){this.active=true;this.panel.hidden=false;this.cancelGesture();this.feedback('Deslize para cima seguindo a guia.')}
follow(dx,dy,height){if(Math.abs(dx)>height*.48){this.invalid=true;this.feedback('Tente seguir a guia sem desviar para os lados.')}this.progress=Math.max(0,Math.min(1,dy/(height*.72)));this.panel.querySelector('#castThumb').style.transform='translateY('+(-Math.min(height*.72,Math.max(0,dy)))+'px)';if(!this.invalid)this.feedback(this.progress>=.66?'Solte para lançar.':'Leve a linha até a estrela.')}
feedback(s){this.panel.querySelector('#castFeedback').textContent=s}
launch(){if(!this.active||this.invalid)return;let power=Math.max(.6,this.progress||.8);this.close();this.onLaunch(power)}
cancelGesture(){this.id=null;this.progress=0;this.invalid=false;this.panel.querySelector('#castThumb').style.transform=''}
close(){this.active=false;this.panel.hidden=true;this.cancelGesture()}
dispose(){this.close();this.panel.remove()}
}
